using Astronomy.MediaFactory.Core.DocumentaryBlueprint;using Astronomy.MediaFactory.ProductionAdapters;using Xunit;
namespace Astronomy.MediaFactory.Tests.ProductionAdapters;
public sealed class DocumentaryMediaVerificationResultMapperTests {
 [Fact] public async Task Verified_result_mapping_preserves_artifact_and_measurements(){await using var f=await DocumentaryMediaVerificationAdapterFixture.SceneVideo();f.ProviderBinding.Response=new(true,new(true,2000,true,true,false,1920,1080,30,48000,2,"mp4"),null);var x=await f.Adapter.VerifyAsync(f.Request,f.ExecutionContext,f.AttemptContext,f.Workspace,default);var m=new DocumentaryMediaVerificationResultMapper().Map(f.Request,x);Assert.Equal(DocumentaryMediaAssetStatus.Verified,m.Status);Assert.Equal(f.Request.AssetId,m.AssetId);Assert.Equal(f.Descriptor.ContentIdentity,m.ContentIdentity);Assert.Equal(f.Descriptor.Checksum,m.Checksum);Assert.Equal(2000,m.DurationMilliseconds);Assert.Equal(1920,m.Width);Assert.Equal(1080,m.Height);Assert.Equal(30,m.FrameRate);Assert.Equal(48000,m.SampleRate);Assert.Equal(2,m.ChannelCount);Assert.Equal(1,m.AttemptCount);Assert.Equal("verification-correlation",m.CorrelationId);}
 [Fact] public void Policy_failure_maps_to_failed_asset_result(){var r=Request();var f=new DocumentaryProductionFailure(DocumentaryProductionFailureCode.DimensionMismatch,"safe");var x=new DocumentaryProductionMediaVerificationAdapterResult(true,false,null,null,f,"p","p","a",DocumentaryPhysicalArtifactKind.SceneVideo,DocumentaryMediaAssetType.SceneVideo,DocumentaryMediaAssetFormat.Mp4);Assert.Equal(DocumentaryMediaAssetStatus.Failed,new DocumentaryMediaVerificationResultMapper().Map(r,x).Status);}
 [Fact] public void Provider_failure_maps_to_failed_asset_result(){var r=Request();var f=new DocumentaryProductionFailure(DocumentaryProductionFailureCode.ProviderTimeout,"safe");var x=new DocumentaryProductionMediaVerificationAdapterResult(false,false,null,null,f,"p",null,"a",DocumentaryPhysicalArtifactKind.SceneVideo,DocumentaryMediaAssetType.SceneVideo,DocumentaryMediaAssetFormat.Mp4);var m=new DocumentaryMediaVerificationResultMapper().Map(r,x);Assert.Equal("ProviderTimeout",m.FailureCode);Assert.Equal("safe",m.FailureMessage);}
 static DocumentaryMediaVerificationRequest Request()=>new("a",DocumentaryMediaAssetType.SceneVideo,DocumentaryMediaAssetFormat.Mp4,DocumentaryPhysicalArtifactKind.SceneVideo,"c",1);
}
